WITH Numbered AS (
    SELECT Id, Email, CreatedAt,
           ROW_NUMBER() OVER (
               PARTITION BY Email          -- what makes a row a duplicate
               ORDER BY CreatedAt, Id      -- the oldest copy wins
           ) AS rn
    FROM dbo.Customers
)
DELETE FROM Numbered
WHERE rn > 1;

-- Stop it happening again
ALTER TABLE dbo.Customers ADD CONSTRAINT UQ_Customers_Email UNIQUE (Email);

-- A table variable survives a rollback: handy for keeping log rows
DECLARE @log TABLE (Msg nvarchar(200));
BEGIN TRAN;
    INSERT @log VALUES (N'step 1 done');
ROLLBACK;
SELECT * FROM @log;          -- still returns the row

-- A large, reused intermediate result: #temp with an index and statistics
SELECT CustomerId, SUM(Amount) AS Total
INTO #Totals
FROM dbo.Orders
GROUP BY CustomerId;

CREATE CLUSTERED INDEX IX_Totals ON #Totals (CustomerId);

CREATE TABLE dbo.Orders (
    OrderId    int IDENTITY(1,1) NOT NULL,
    CustomerId int           NOT NULL,
    OrderDate  datetime2(0)  NOT NULL,
    Amount     decimal(18,2) NOT NULL,
    CONSTRAINT PK_Orders PRIMARY KEY CLUSTERED (OrderId)     -- the table itself
);

-- Separate structure: CustomerId keys + the clustered key (OrderId) as the locator
CREATE NONCLUSTERED INDEX IX_Orders_CustomerId
    ON dbo.Orders (CustomerId);

CREATE TABLE dbo.Documents (
    DocumentId uniqueidentifier NOT NULL DEFAULT NEWID(),
    CreatedAt  datetime2(3)     NOT NULL DEFAULT SYSUTCDATETIME(),
    Title      nvarchar(200)    NOT NULL,
    CONSTRAINT PK_Documents PRIMARY KEY NONCLUSTERED (DocumentId)
);

-- Cluster on an ever-increasing column instead
CREATE CLUSTERED INDEX CX_Documents_CreatedAt
    ON dbo.Documents (CreatedAt);

CREATE INDEX IX_Orders_Customer_Date ON dbo.Orders (CustomerId, OrderDate);

-- Seek on the leading column + range on the second: efficient
SELECT OrderId FROM dbo.Orders
WHERE CustomerId = 42 AND OrderDate >= '2025-01-01';

-- Leading column missing: can't seek with this index (expect a scan)
SELECT OrderId FROM dbo.Orders
WHERE OrderDate >= '2025-01-01';

-- Index has CustomerId only; the query also needs OrderDate and Amount
CREATE INDEX IX_Orders_CustomerId ON dbo.Orders (CustomerId);

SELECT OrderId, OrderDate, Amount       -- OrderDate, Amount -> Key Lookup
FROM dbo.Orders
WHERE CustomerId = 42;

-- Cover it: the same seek, no lookup
CREATE INDEX IX_Orders_CustomerId
    ON dbo.Orders (CustomerId)
    INCLUDE (OrderDate, Amount)
    WITH (DROP_EXISTING = ON);

-- When were the statistics on a table last updated, and how stale are they?
SELECT s.name AS stats_name,
       sp.last_updated,
       sp.rows,
       sp.modification_counter
FROM sys.stats AS s
CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) AS sp
WHERE s.object_id = OBJECT_ID('dbo.Orders');

UPDATE STATISTICS dbo.Orders IX_Orders_Customer_Date WITH FULLSCAN;
DBCC SHOW_STATISTICS ('dbo.Orders', IX_Orders_Customer_Date);

-- Column: AccountCode varchar(20), indexed
-- BAD: nvarchar parameter -> the column is converted, the seek can be lost
DECLARE @code nvarchar(20) = N'ACC-001';
SELECT AccountId FROM dbo.Accounts WHERE AccountCode = @code;

-- GOOD: types match, plain index seek
DECLARE @code2 varchar(20) = 'ACC-001';
SELECT AccountId FROM dbo.Accounts WHERE AccountCode = @code2;

/* C# (ADO.NET):
   cmd.Parameters.AddWithValue("@code", code);                         // sent as NVarChar
   cmd.Parameters.Add("@code", SqlDbType.VarChar, 20).Value = code;    // matches the column
*/

-- Money transfer: both updates or neither
SET XACT_ABORT ON;
BEGIN TRAN;
    UPDATE dbo.Accounts SET Balance = Balance - 100 WHERE AccountId = 1;
    UPDATE dbo.Accounts SET Balance = Balance + 100 WHERE AccountId = 2;
COMMIT;

BEGIN TRAN;
    TRUNCATE TABLE dbo.StagingOrders;
    SELECT COUNT(*) FROM dbo.StagingOrders;   -- 0
ROLLBACK;
SELECT COUNT(*) FROM dbo.StagingOrders;       -- the rows are back

SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRAN;
    SELECT Balance FROM dbo.Accounts WHERE AccountId = 1;   -- S lock kept
    -- another session's UPDATE of this row now waits...
    SELECT Balance FROM dbo.Accounts WHERE AccountId = 1;   -- same value
COMMIT;

-- What people write
SELECT SUM(Amount) FROM dbo.Orders WITH (NOLOCK) WHERE OrderDate >= '2025-01-01';

-- What usually solves the real problem (database-level, test first)
ALTER DATABASE Shop SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;
-- Readers now get the last committed row versions; no dirty reads, no read locks

CREATE OR ALTER PROCEDURE dbo.TransferFunds
    @From int, @To int, @Amount decimal(18,2)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;
            UPDATE dbo.Accounts SET Balance = Balance - @Amount WHERE AccountId = @From;
            UPDATE dbo.Accounts SET Balance = Balance + @Amount WHERE AccountId = @To;
        COMMIT;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        THROW;          -- re-raise to the caller with the original error
    END CATCH
END;

-- Database-level switch (needs no other active connections; ROLLBACK IMMEDIATE kicks them out)
ALTER DATABASE Shop SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;

-- Transaction-level snapshot for a consistent multi-query report
ALTER DATABASE Shop SET ALLOW_SNAPSHOT_ISOLATION ON;
SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
BEGIN TRAN;
    SELECT SUM(Amount) FROM dbo.Orders;
    SELECT COUNT(*)    FROM dbo.OrderLines;   -- same point in time as the first query
COMMIT;

-- Read-then-update without the S -> X conversion deadlock
BEGIN TRAN;
    SELECT Quantity
    FROM dbo.Stock WITH (UPDLOCK)        -- U lock: others can still read, only one can hold U
    WHERE ProductId = 10;

    UPDATE dbo.Stock SET Quantity = Quantity - 1 WHERE ProductId = 10;  -- U -> X
COMMIT;

-- See the locks a session holds
SELECT resource_type, request_mode, request_status, resource_description
FROM sys.dm_tran_locks
WHERE request_session_id = @@SPID;

-- Purge old rows in batches to avoid escalating to a table lock
DECLARE @rows int = 1;
WHILE @rows > 0
BEGIN
    DELETE TOP (4000) FROM dbo.AuditLog
    WHERE CreatedAt < DATEADD(year, -2, SYSUTCDATETIME());
    SET @rows = @@ROWCOUNT;
END;

-- Partition-level escalation on a partitioned table
ALTER TABLE dbo.AuditLog SET (LOCK_ESCALATION = AUTO);

CREATE OR ALTER PROCEDURE dbo.UpsertStock @ProductId int, @Qty int
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRAN;

        UPDATE dbo.Stock WITH (UPDLOCK, HOLDLOCK)
        SET Quantity = @Qty
        WHERE ProductId = @ProductId;

        IF @@ROWCOUNT = 0
            INSERT dbo.Stock (ProductId, Quantity) VALUES (@ProductId, @Qty);

    COMMIT;
END;

