-- Procedure: performs work, can return several things
CREATE OR ALTER PROCEDURE dbo.PlaceOrder @CustomerId int, @OrderId int OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT dbo.Orders (CustomerId, OrderDate) VALUES (@CustomerId, SYSUTCDATETIME());
    SET @OrderId = SCOPE_IDENTITY();
END;
GO

-- Inline TVF: a parameterized view you can join to
CREATE OR ALTER FUNCTION dbo.OrdersForCustomer (@CustomerId int)
RETURNS TABLE
AS RETURN
    SELECT OrderId, OrderDate, Amount
    FROM dbo.Orders
    WHERE CustomerId = @CustomerId;
GO

SELECT c.Name, o.OrderId
FROM dbo.Customers AS c
CROSS APPLY dbo.OrdersForCustomer(c.CustomerId) AS o;

CREATE OR ALTER PROCEDURE dbo.GetCustomerOrders
    @CustomerId int,
    @OrderCount int OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM dbo.Customers WHERE CustomerId = @CustomerId)
        THROW 50001, 'Customer not found.', 1;     -- an error, not a magic return code

    SELECT OrderId, OrderDate, Amount               -- result set
    FROM dbo.Orders
    WHERE CustomerId = @CustomerId;

    SET @OrderCount = @@ROWCOUNT;                   -- still updated with NOCOUNT ON
    RETURN 0;                                       -- status code
END;
GO

DECLARE @n int, @rc int;
EXEC @rc = dbo.GetCustomerOrders @CustomerId = 42, @OrderCount = @n OUTPUT;
SELECT @rc AS ReturnCode, @n AS OrderCount;

-- These two behave the same way for plan caching:
EXEC dbo.GetOrdersByCustomer @CustomerId = 42;

EXEC sp_executesql
     N'SELECT OrderId, OrderDate, Amount FROM dbo.Orders WHERE CustomerId = @CustomerId',
     N'@CustomerId int',
     @CustomerId = 42;

-- This one is the real problem: a new plan per literal, and injectable if built from input
-- EXEC ('SELECT OrderId FROM dbo.Orders WHERE CustomerId = ' + @input);

-- Windows group as a login (manage people in AD, not in SQL Server)
CREATE LOGIN [CONTOSO\ShopApp-Readers] FROM WINDOWS;

-- SQL login only when required, with policy enforcement
CREATE LOGIN shop_api WITH PASSWORD = N'<strong password here>',
    CHECK_POLICY = ON, CHECK_EXPIRATION = ON;

-- Connection strings (C#)
-- Server=sql01;Database=Shop;Integrated Security=true;Encrypt=true;
-- Server=sql01;Database=Shop;User Id=shop_api;Password=...;Encrypt=true;

CREATE ROLE SalesReaders;
ALTER ROLE SalesReaders ADD MEMBER Jae;

GRANT SELECT ON SCHEMA::Sales TO SalesReaders;       -- schema-level, via a role
GRANT SELECT ON OBJECT::Sales.OrderStatus TO Jae;    -- Jae also has a direct grant

-- WRONG way to undo the role grant: Jae loses access too (DENY beats Jae's own GRANT)
-- DENY SELECT ON SCHEMA::Sales TO SalesReaders;

-- RIGHT: remove the role's grant; Jae keeps the direct grant
REVOKE SELECT ON SCHEMA::Sales FROM SalesReaders;

CREATE OR ALTER PROCEDURE dbo.SearchOrders
    @SortColumn sysname,
    @CustomerId int
AS
BEGIN
    SET NOCOUNT ON;

    -- Identifier: whitelist + QUOTENAME (values can't do this job)
    IF @SortColumn NOT IN (N'OrderDate', N'Amount', N'OrderId')
        THROW 50002, 'Invalid sort column.', 1;

    DECLARE @sql nvarchar(max) =
        N'SELECT OrderId, OrderDate, Amount
          FROM dbo.Orders
          WHERE CustomerId = @CustomerId
          ORDER BY ' + QUOTENAME(@SortColumn) + N';';

    -- Value: a real parameter
    EXEC sp_executesql @sql, N'@CustomerId int', @CustomerId = @CustomerId;
END;

/* C#:
   cmd.Parameters.Add("@CustomerId", SqlDbType.Int).Value = customerId;   // safe
   $"... WHERE Name = '{name}'"  passed to ExecuteSqlRaw / SqlCommand      // injectable
*/
